function renderIcons(){document.querySelectorAll('[data-icon]').forEach(el=>el.outerHTML=icon(el.dataset.icon));}
function renderNav(){document.querySelector('#navigation').innerHTML=nav.map(n=>n.length===1?`<div class="nav-group">${n[0]}</div>`:`<a href="#${n[0]}" class="nav-link ${n[4]?'sub':''} ${page===n[0]?'active':''}" ${page===n[0]?'aria-current="page"':''}>${n[2]?icon(n[2]):''}<span>${n[1]}</span>${n[3]?`<span class="count">${n[3]}</span>`:''}</a>`).join('');}
function heading(title,desc,buttons='',eyebrow='마음든든 파트너센터'){return `<section class="page-heading"><div><div class="eyebrow">${eyebrow}</div><h1>${title}</h1><p>${desc}</p></div><div class="heading-buttons">${buttons}</div></section>`;}
function metric(label,value,unit,ic,trend,foot,warning=false){return `<article class="metric"><div class="metric-head">${label}<span class="metric-icon">${icon(ic)}</span></div><div class="metric-value">${value}<span>${unit}</span></div><div class="metric-foot"><span class="metric-trend ${warning?'warning':''}">${trend}</span>${foot}</div></article>`;}
function dateControl(){return `<button class="date-control" data-action="date">${icon('calendar')}<span id="dateLabel">2026.11.01 – 2026.11.16</span>${icon('chevron-down')}</button>`;}
function datePanel(){return `<div class="date-range-panel" id="datePanel" hidden><span class="toolbar-note">예시 조회 기간</span>${btn('이번 달','','data-action="range" data-range="month"','small')}${btn('이번 주','','data-action="range" data-range="week"','small')}<label>시작 <input aria-label="시작일" type="date" id="dateFrom" value="2026-11-01"></label><label>종료 <input aria-label="종료일" type="date" id="dateTo" value="2026-11-16"></label>${btn('적용','check','data-action="apply-date"','small primary')}</div>`;}
function lineChart(){let a=chartPeriod==='week'?[11,16,13,23,18,27,20]:[12,20,17,29,23,36,28];let b=chartPeriod==='week'?[4,7,6,12,8,15,10]:[5,10,7,15,11,20,15];let labels=chartPeriod==='week'?['11.10','11.11','11.12','11.13','11.14','11.15','11.16']:['11.01','11.03','11.05','11.07','11.09','11.12','11.16'];let max=chartPeriod==='week'?30:40;const coords=v=>v.map((n,i)=>[44+i*88,166-n/max*135]);const d=v=>coords(v).map((p,i)=>(i?'L':'M')+p.join(' ')).join(' ');let p=coords(a),last=p[p.length-1];return `<svg class="line-chart" viewBox="0 0 615 200" role="img" aria-label="${chartPeriod==='week'?'주간':'월간'} 상담 및 가입 현황 예시 차트"><defs><linearGradient id="chartArea" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="#a8c4a3" stop-opacity=".22"/><stop offset="1" stop-color="#a8c4a3" stop-opacity="0"/></linearGradient></defs>${[0,1,2,3].map(i=>`<line class="grid" x1="43" y1="${31+i*45}" x2="583" y2="${31+i*45}"/><text x="12" y="${35+i*45}">${Math.round(max*(3-i)/3)}</text>`).join('')}<path d="${d(a)} L572 166 L44 166 Z" fill="url(#chartArea)"/><path class="chart-secondary" d="${d(b)}"/><path class="chart-main" d="${d(a)}"/>${p.map((v,i)=>`<circle cx="${v[0]}" cy="${v[1]}" r="${i===6?4:2.5}" fill="#fff" stroke="#397058" stroke-width="2"><title>${labels[i]} 상담 ${a[i]}건 · 가입 ${b[i]}건</title></circle>`).join('')}<rect x="${last[0]-18}" y="${last[1]-32}" width="36" height="22" rx="5" fill="#376651"/><text x="${last[0]}" y="${last[1]-17}" text-anchor="middle" style="fill:white;font-size:10px">${a[6]}건</text>${labels.map((v,i)=>`<text x="${44+i*88}" y="190" text-anchor="middle">${v}</text>`).join('')}</svg>`;}
function chartPanel(){return `<section class="panel"><div class="panel-top"><div><h2>상담 · 가입 현황</h2><p class="panel-subtitle">고객과의 첫 만남부터 가입까지</p></div><div class="segmented" aria-label="차트 조회 기간"><button data-action="chart" data-value="week" class="${chartPeriod==='week'?'active':''}">주간</button><button data-action="chart" data-value="month" class="${chartPeriod==='month'?'active':''}">월간</button></div></div><div class="chart-summary"><span class="legend-item"><i class="legend-dot"></i>상담 접수</span><span class="legend-item"><i class="legend-dot sage"></i>정상 가입</span><span style="margin-left:auto">단위: 건</span></div><div class="chart-wrap" id="chartWrap">${lineChart()}</div></section>`;}
function channelPanel(){return `<section class="panel channel-panel"><div class="panel-top"><div><h2>상담 유입 경로</h2><p class="panel-subtitle">어디에서 마음든든을 만났을까요?</p></div>${icon('more')}</div><div class="circle-chart" role="img" aria-label="예시 상담 128건 중 상품 랜딩 56건, 파트너 36건, 인스타그램 24건, 직접 등록 12건"><div class="circle-chart-content"><b>128</b><small>전체 상담</small></div></div><div class="channel-list">${[['상품 랜딩',56,'44%','#376b56'],['파트너',36,'28%','#96b08b'],['인스타그램',24,'19%','#c9d4b8'],['직접 등록',12,'9%','#dcd9c6']].map(v=>`<div class="channel-row"><i style="background:${v[3]}"></i>${v[0]}<b>${v[1]}건</b><span>${v[2]}</span></div>`).join('')}</div></section>`;}
function customerTable(rows,compact=false){return `<div class="table-scroll"><table class="${compact?'dashboard-table':'full-table'}"><thead><tr>${compact?'':`<th><input type="checkbox" class="checkbox" aria-label="현재 목록 전체 선택" data-select-all></th>`}<th>고객명</th><th>가입 상품</th><th>진행 상태</th>${compact?'':`<th>담당 파트너</th><th>구좌</th>`}<th>유입 경로</th><th>${compact?'접수 시간':'접수 일시'}</th>${compact?'':`<th>관리</th>`}</tr></thead><tbody>${rows.length?rows.map((d,i)=>`<tr class="clickable-row" data-customer="${d.id}" tabindex="0" aria-label="${d.name} 고객 상세"><td ${compact?'hidden':''}><input class="checkbox row-check" type="checkbox" aria-label="${d.name} 선택"></td><td><div class="person"><span class="person-circle ${i%2?'alt':''}">${d.name[0]}</span><span><strong>${d.name}</strong><small>${compact?d.phone:d.id+' · '+d.phone}</small></span></div></td><td>마음든든 <strong>${d.product}</strong></td><td>${pill(d.status)}</td>${compact?'':`<td>${d.partner}</td><td>${d.units}구좌</td>`}<td>${d.channel}</td><td class="amount muted">${compact?d.time.split(' ')[1]:d.time}</td>${compact?'':`<td><button class="row-more" data-customer="${d.id}" aria-label="${d.name} 상세보기">${icon('chevron-right')}</button></td>`}</tr>`).join(''):tableEmpty(compact?5:9)}</tbody></table></div>`;}
function dashboard(){return `${heading('좋은 하루예요, 관리자님.','고객을 위한 든든한 준비, 오늘의 영업 현황을 확인하세요.',dateControl()+btn('고객 등록','plus','data-action="new-customer"','primary'),'2026년 11월 16일 월요일')}${datePanel()}<section class="metrics-grid" aria-label="영업 핵심 지표">${metric('전체 상담 접수','128','건','users','↗ 18.5%','지난 기간 대비')}${metric('상담 진행중','46','건','phone','12건 대기','상담 연결이 필요해요',true)}${metric('정상 가입','62','건','shield','↗ 12.7%','지난 기간 대비')}${metric('상담 → 가입 전환율','48.4','%','trend','↗ 3.2%p','지난 기간 대비')}</section><div class="dashboard-middle">${chartPanel()}<section class="panel task-panel"><div class="task-title"><h2>오늘의 체크포인트</h2>${pill('TO DO','gray')}</div><div class="task-content"><a href="#customers" class="task-row" data-task-filter="접수대기"><span class="task-icon">${icon('phone')}</span><span><strong>첫 상담을 기다려요</strong><small>신규 접수 · 미배정 고객</small></span><b>12</b>${icon('chevron-right')}</a><a href="#customers" class="task-row" data-task-filter="녹취완료"><span class="task-icon">${icon('mic')}</span><span><strong>가입 확인이 필요해요</strong><small>녹취 완료 · 출금 확인</small></span><b>8</b>${icon('chevron-right')}</a><a href="#overdue-new" class="task-row"><span class="task-icon">${icon('clock')}</span><span><strong>납입 상태를 확인해요</strong><small>연체 고객 · 후속 상담</small></span><b>5</b>${icon('chevron-right')}</a></div><div class="task-foot">${icon('info')}처리가 필요한 업무부터 확인하세요.</div></section></div><div class="dashboard-lower"><section class="panel table-panel"><div class="panel-top"><div><h2>최근 상담 고객</h2><p class="panel-subtitle">최근 접수된 상담을 빠르게 확인하세요.</p></div><a class="button plain" href="#customers">전체 보기 ${icon('arrow-right')}</a></div>${customerTable(data.slice(0,5),true)}<div class="table-panel-foot"><span>고객을 선택하면 상세 정보를 확인할 수 있습니다.</span><span>최근 5건</span></div></section>${channelPanel()}</div><div class="bottom-strip"><a class="announcement" href="#resources">${icon('megaphone')}<div><p>파트너를 위한 마음든든 상담 가이드</p><small>상품 설명부터 가입 전 확인사항까지, 한 곳에서 확인하세요.</small></div><span>자료실 ${icon('arrow-up-right')}</span></a><a class="announcement" href="https://sono-maeum.vercel.app/" target="_blank" rel="noreferrer">${icon('leaf')}<div><p>고객에게 전하는 든든한 마음</p><small>마음든든 상품 랜딩페이지 바로가기</small></div><span>${icon('external')}</span></a></div>`;}
function customers(){const tabs=['전체','접수대기','상담중','녹취완료','정상가입','보류','부재'];return `${heading('고객 관리','상담 접수부터 가입까지, 고객의 여정을 한눈에 관리하세요.',btn('엑셀 업로드','upload','data-action="import"')+btn('고객 등록','plus','data-action="new-customer"','primary'))}<section class="panel"><div class="tabs" aria-label="고객 상태 필터">${tabs.map(t=>`<button class="tab ${customerFilter===t?'active':''}" data-action="customer-tab" data-value="${t}">${t}<span class="tab-count">${t==='전체'?data.length:data.filter(d=>d.status===t).length}</span></button>`).join('')}</div><div class="filter-bar"><label class="search-field">${icon('search')}<input id="customerSearch" aria-label="고객 검색" placeholder="고객명, 연락처, 접수번호 검색" value="${safe(search)}"></label><select id="productFilter" aria-label="상품 선택">${['전체 상품','마음든든 3','마음든든 4','마음든든 5'].map(x=>`<option ${x===productFilter?'selected':''}>${x}</option>`).join('')}</select><select id="partnerFilter" aria-label="파트너 선택">${['전체 파트너','본사 직영','파트너 A','파트너 B','파트너 C'].map(x=>`<option ${x===partnerFilter?'selected':''}>${x}</option>`).join('')}</select>${btn('초기화','refresh','data-action="reset-filter"','small')}<span class="filter-end">${btn('엑셀 다운로드','download','data-action="export"','small')}</span></div><div class="table-count" id="customerCount"></div><div id="customerTable"></div><div class="table-panel-foot"><span id="customerRange"></span><div class="pagination" id="customerPagination"></div></div></section><div class="section-note">${icon('info')}이 목록은 화면 검토용 예시입니다. 고객 배정, 녹취 업로드, 본사 접수 연동은 기능 개발 단계에서 연결합니다.</div>`;}
function fillCustomerTable(){let rows=data.filter(d=>(customerFilter==='전체'||d.status===customerFilter)&&(!search||`${d.name} ${d.phone} ${d.id}`.toLowerCase().includes(search.toLowerCase()))&&(productFilter==='전체 상품'||'마음든든 '+d.product===productFilter)&&(partnerFilter==='전체 파트너'||d.partner===partnerFilter));let pages=Math.max(1,Math.ceil(rows.length/8));pageNumber=Math.min(pageNumber,pages);document.querySelector('#customerCount').innerHTML=`검색 결과 <strong>${rows.length}</strong>명 <span class="muted">· 샘플 고객</span>`;document.querySelector('#customerTable').innerHTML=customerTable(rows.slice((pageNumber-1)*8,pageNumber*8));document.querySelector('#customerRange').textContent=`${rows.length?((pageNumber-1)*8+1):0}–${Math.min(pageNumber*8,rows.length)} / ${rows.length}명`;document.querySelector('#customerPagination').innerHTML=`<button data-page="${pageNumber-1}" ${pageNumber===1?'disabled':''} aria-label="이전 페이지">‹</button>${Array.from({length:pages},(_,i)=>`<button data-page="${i+1}" class="${pageNumber===i+1?'active':''}" aria-label="${i+1}페이지">${i+1}</button>`).join('')}<button data-page="${pageNumber+1}" ${pageNumber===pages?'disabled':''} aria-label="다음 페이지">›</button>`;}
function partnerPage(){return `${heading('파트너 관리','함께 성장하는 파트너, 조직과 영업 활동을 연결하세요.',btn('파트너 등록','plus','data-action="new-partner"','primary'))}<div class="metrics-grid compact-metrics">${metric('전체 파트너','4','개사','network','함께하는 파트너','본사 직영 포함')}${metric('운영중 파트너','4','개사','check-circle','100%','운영 비율')}${metric('파트너 상담 접수','128','건','phone','이번 달','예시 접수 실적')}${metric('정상 가입','62','건','shield','48.4%','예시 가입 전환율')}</div><div class="partner-layout"><section class="panel organization"><h2>파트너 조직</h2><button class="tree-row selected" data-org="all">${icon('network')}전체 조직 <b>4</b></button><button class="tree-row" data-org="라이프앤조이">${icon('building')}라이프앤조이</button><button class="tree-row subtree" data-org="본사 직영">${icon('users')}본사 직영</button><button class="tree-row subtree" data-org="파트너 A">${icon('users')}파트너 A</button><button class="tree-row subtree" data-org="파트너 B">${icon('users')}파트너 B</button><button class="tree-row subtree" data-org="파트너 C">${icon('users')}파트너 C</button><p class="tree-caption">조직을 선택하면 해당 파트너의<br>기본 정보와 실적을 확인합니다.</p></section><section class="panel"><div class="filter-bar"><label class="search-field">${icon('search')}<input aria-label="파트너 검색" id="partnerSearch" placeholder="파트너명, 담당자 검색"></label><span class="filter-end">전체 <b>4</b>개사</span></div><div class="table-scroll"><table class="full-table"><thead><tr><th>파트너 정보</th><th>상위 조직</th><th>담당자</th><th>상담 / 가입</th><th>상태</th><th></th></tr></thead><tbody id="partnerRows">${partnerRows(partners)}</tbody></table></div><div class="overview-label">파트너명과 실적은 모두 디자인용 예시입니다.</div></section></div>`;}
function partnerRows(rows){return rows.length?rows.map(d=>`<tr class="clickable-row" data-partner="${d[0]}"><td><div class="person"><span class="person-circle">${icon('building')}</span><span><strong>${d[0]}</strong><small>${d[1]}</small></span></div></td><td>${d[2]}</td><td>${d[3]}</td><td><strong>${d[4]}</strong> / ${d[5]}건</td><td>${pill(d[6])}</td><td>${btn('상세','chevron-right',`data-partner="${d[0]}"`,'small')}</td></tr>`).join(''):tableEmpty(6);}
function applications(){let apps=[['AP-003','신규 파트너 D','법인','홍담당','온라인 모집','11.16 14:20','심사중'],['AP-002','신규 파트너 E','개인사업자','이담당','파트너 추천','11.15 11:42','심사중'],['AP-001','신규 파트너 F','법인','최담당','온라인 모집','11.14 09:15','서류보완']];return `${heading('입점 신청','신규 파트너의 첫걸음, 신청 내용과 심사 진행을 확인하세요.',btn('신청 현황 다운로드','download','data-action="export"'))}<div class="metrics-grid compact-metrics">${metric('전체 신청','8','건','building','이번 달','예시 신청 현황')}${metric('심사중','2','건','clock','검토 필요','신규 신청')}${metric('서류보완','1','건','file','확인 필요','보완 요청')}${metric('승인완료','5','건','check-circle','심사 완료','예시 처리 현황')}</div><section class="panel"><div class="table-headline"><h2>검토가 필요한 신청 <span class="pill orange">3</span></h2><span class="toolbar-note">신청일 최신순</span></div><div class="table-scroll"><table class="full-table"><thead><tr><th>신청번호</th><th>파트너명</th><th>사업자 유형</th><th>담당자</th><th>신청 경로</th><th>신청일</th><th>심사 상태</th><th>관리</th></tr></thead><tbody>${apps.map(d=>`<tr><td class="muted">${d[0]}</td><td><strong>${d[1]}</strong></td><td>${d[2]}</td><td>${d[3]}</td><td>${d[4]}</td><td>${d[5]}</td><td>${pill(d[6],d[6]==='서류보완'?'gray':'orange')}</td><td>${btn('신청서 보기','chevron-right',`data-application="${d[1]}"`,'small')}</td></tr>`).join('')}</tbody></table></div><div class="table-panel-foot"><span>실제 신청 및 심사 이력은 아직 연결되지 않았습니다.</span><span>3건 표시</span></div></section>`;}
function products(){return `${heading('상품관리','랜딩페이지와 상담에서 안내하는 상품 정보를 한곳에서 확인하세요.',`<a class="button" href="https://sono-maeum.vercel.app/" target="_blank" rel="noreferrer">${icon('external')}랜딩페이지 확인</a>`)}<div class="section-note" style="margin-top:0">${icon('info')}아래 금액은 제공하신 랜딩의 현재 표기를 참고했습니다. 최종 승인 자료 대조 후 운영용 상품 정보로 확정합니다.</div><div class="product-grid">${[3,4,5].map((n,i)=>{let prices=['32,000','43,000','54,000'],totals=['3,072,000','4,128,000','5,184,000'];return `<article class="panel product-card ${n===4?'featured':''}"><div class="product-topline">MAEUM ${pill('자료 대조 대기','gray')}</div><h2>마음든든 ${n}</h2><p>${['기본에 충실한 든든한 준비','필요한 지원을 더한 준비','넉넉한 인력과 용품 구성'][i]}</p><span class="plan-number">${n}</span><div class="product-price"><small>월</small>${prices[i]}<small> 원</small></div><div class="product-meta">96회 납입 · 총 ${totals[i]}원</div><div class="product-feature"><span>장례의전 도우미</span><b>${[3,4,6][i]}명</b></div><div class="product-feature"><span>잔금 보장 구간</span><b>25~84회차 · 조건 충족 시</b></div><div class="product-feature"><span>정보 출처</span><b>제공 랜딩페이지</b></div>${btn('상품 정보 확인','arrow-right',`data-product="${n}"`,n===4?'primary':'')}</article>`}).join('')}</div><div class="management-title"><h2>마음든든 2·5·1 구조</h2><p>상담 설명용 · 랜딩 표기 기준</p></div><div class="product-flow"><div class="flow-step"><span class="number">2</span><span><b>년 준비</b><small>1~24회차 · 보장 제외</small></span></div><div class="flow-step"><span class="number">5</span><span><b>년 잔금 보장</b><small>25~84회차 · 지정 1인 · 조건 충족 시</small></span></div><div class="flow-step"><span class="number">1</span><span><b>년 납입 마무리</b><small>85~96회차 · 보장 제외</small></span></div></div><div class="section-note">${icon('info')}96회 납입 완료와 만기 환급 시점은 다릅니다. 해약·환급·서비스 이용 조건은 최종 계약 기준 확인이 필요합니다.</div>`;}
function promotions(){return `${heading('프로모션','파트너 영업을 위한 캠페인과 홍보 자료를 관리하세요.',btn('프로모션 등록','plus','data-action="new-promotion"','primary'))}<div class="campaign-grid">${[['초안','마음든든,<br>첫 만남의 시작','신규 상담 캠페인','상품 랜딩에서 상담으로 이어지는 기본 캠페인 구성안입니다.','상품 랜딩 · 인스타그램',''],['검토대기','가족을 위한 준비,<br>함께 알아보세요','파트너 상담 가이드','파트너가 일관된 기준으로 상품을 안내하기 위한 상담 자료입니다.','파트너센터 · 자료실','dark'],['초안','가입 전,<br>함께 확인해요','가입 전 확인 카드뉴스','납입, 서비스, 해약 조건을 차분하게 설명하는 콘텐츠 구성안입니다.','인스타그램 · 쇼츠','sand']].map((d,i)=>`<article class="panel"><div class="campaign-art ${d[5]}"><small>MAEUM PARTNER CAMPAIGN</small><strong>${d[1]}</strong></div><div class="campaign-body">${pill(d[0],d[0]==='초안'?'gray':'orange')}<h3>${d[2]}</h3><p>${d[3]}</p><div class="campaign-info"><span>${d[4]}</span><button class="button plain" data-campaign="${i}">상세 보기 ${icon('arrow-right')}</button></div></div></article>`).join('')}</div><div class="section-note">${icon('info')}화면 구성 예시입니다. 실제 프로모션 조건·혜택·집행 일정은 등록되지 않았으며 외부 채널에 게시되지 않습니다.</div>`;}
function overdue(){let newer=page==='overdue-new';return `${heading(newer?'연체 관리 · 8월 이후 가입':'연체 관리','납입 상태와 후속 상담을 함께 확인해, 고객의 유지를 돕습니다.',btn('납입 내역 업로드','upload','data-action="import"')+btn('엑셀 다운로드','download','data-action="export"'))}<div class="metrics-grid compact-metrics">${metric('확인 대상 고객',newer?'24':'46','명','users','조회 범위',newer?'8월 이후 가입':'전체 가입 고객')}${metric('정상 납입',newer?'19':'38','명','check-circle','납입 확인','예시 납입 상태')}${metric('연체 확인 필요',newer?'5':'8','명','clock','후속 상담','고객 상태 확인',true)}${metric('이번 달 해결',newer?'3':'6','건','refresh','납입 재개','예시 처리 현황')}</div><section class="panel"><div class="tabs"><button class="tab active" data-action="arrears-tab" data-value="all">연체 확인 필요 <span class="tab-count">5</span></button><button class="tab" data-action="arrears-tab" data-value="scheduled">상담 예정</button><button class="tab" data-action="arrears-tab" data-value="resolved">해결 완료</button></div><div class="filter-bar"><label class="search-field">${icon('search')}<input id="arrearsSearch" aria-label="연체 고객 검색" placeholder="고객명, 파트너명 검색"></label><span class="filter-end">납입 및 환수 기준은 운영 정책 확정 후 적용</span></div><div class="table-scroll"><table class="full-table"><thead><tr><th>고객명</th><th>파트너</th><th>가입 상품</th><th>가입일</th><th>납입 회차</th><th>연체 횟수</th><th>상담 상태</th><th>관리</th></tr></thead><tbody id="arrearsRows">${arrearsRows('all')}</tbody></table></div><div class="overview-label">정산·환수 계산과 실제 납입 내역은 연결되지 않았습니다.</div></section>`;}
function arrearsRows(mode,query=''){let rows=data.slice(0,5).filter((d,i)=>mode==='all'||(mode==='scheduled'?i<2:i>=2));rows=rows.filter(d=>(d.name+d.partner).includes(query));return rows.length?rows.map((d,i)=>`<tr><td><div class="person"><span class="person-circle">${d.name[0]}</span><span><strong>${d.name}</strong><small>${d.phone}</small></span></div></td><td>${d.partner}</td><td>마음든든 ${d.product}</td><td class="muted">2026.0${i+8>9?9:i+8}.12</td><td>${i+2}회</td><td>${pill(mode==='resolved'?'해결':`${i%3+1}회 연체`,mode==='resolved'?'green':i%3===2?'red':'orange')}</td><td>${pill(mode==='resolved'?'납입 확인':i<2?'상담 예정':'연락 필요',mode==='resolved'?'green':i<2?'blue':'gray')}</td><td>${btn('상세','chevron-right',`data-customer="${d.id}"`,'small')}</td></tr>`).join(''):tableEmpty(8);}
function statistics(){return `${heading('통계','접수에서 가입까지, 파트너와 유입 채널의 흐름을 살펴보세요.',dateControl()+btn('리포트 다운로드','download','data-action="export"'))}${datePanel()}<div class="metrics-grid compact-metrics">${metric('상담 접수','128','건','users','↗ 18.5%','지난 기간 대비')}${metric('정상 가입','62','건','shield','↗ 12.7%','지난 기간 대비')}${metric('가입 전환율','48.4','%','trend','↗ 3.2%p','지난 기간 대비')}${metric('운영 파트너','4','개사','network','전체 운영중','본사 직영 포함')}</div><div class="stats-grid">${chartPanel()}<section class="panel"><div class="panel-top"><div><h2>상품별 가입 현황</h2><p class="panel-subtitle">예시 정상 가입 62건 기준</p></div></div><div class="horizontal-bars">${[['마음든든 3',14,22.6],['마음든든 4',22,35.5],['마음든든 5',26,41.9]].map(d=>`<div class="bar-row"><div class="bar-label"><span>${d[0]}</span><b>${d[1]}건 <small class="muted">(${d[2]}%)</small></b></div><div class="bar-track"><span style="width:${d[2]*2}%;background:${d[0].endsWith('5')?'#416f4f':'#a6bd95'}"></span></div></div>`).join('')}</div></section></div><section class="panel" style="margin-top:21px"><div class="table-headline"><h2>파트너별 영업 실적</h2><span class="toolbar-note">디자인용 예시 실적</span></div><div class="table-scroll"><table class="full-table"><thead><tr><th>파트너</th><th>상담 접수</th><th>정상 가입</th><th>가입 전환율</th><th>진행 현황</th></tr></thead><tbody>${partners.map(d=>`<tr><td><strong>${d[0]}</strong></td><td>${d[4]}건</td><td>${d[5]}건</td><td class="text-green">${(d[5]/d[4]*100).toFixed(1)}%</td><td><div class="bar-track" style="width:160px"><span style="width:${d[5]/d[4]*100}%"></span></div></td></tr>`).join('')}</tbody></table></div></section>`;}
function resources(){let list=[['PDF','마음든든 상품 안내서','3·4·5 상품의 납입 조건과 서비스 구성을 확인하는 자료.','상품 자료'],['PDF','가입 전 확인 체크리스트','납입, 서비스, 해약 조건을 빠짐없이 설명하기 위한 자료.','상담 자료'],['DOC','파트너 상담 스크립트','첫 상담부터 가입 안내까지, 상황별 상담 흐름.','상담 자료'],['XLS','고객 접수 양식','고객 기본 정보와 관심 상품을 등록하는 표준 양식.','업무 양식'],['PDF','브랜드 디자인 가이드','마음든든의 색상과 로고, 홍보물 활용 기준.','홍보 자료'],['PDF','파트너센터 이용 가이드','고객 조회와 상담 기록, 영업관리 화면 안내.','운영 가이드']];return `${heading('자료실','정확한 안내와 편리한 영업을 위한 자료를 모았습니다.',btn('자료 등록','plus','data-action="new-resource"','primary'))}<div class="section-note" style="margin-top:0">${icon('folder')}자료 카드의 배치 예시입니다. 승인된 실제 파일은 기능 개발 후 등록할 수 있습니다.</div><div class="resource-grid">${list.map((d,i)=>`<article class="panel resource-card"><div class="file-icon ${d[0]==='PDF'?'pdf':''}">${d[0]}</div>${pill(d[3],'gray')}<h3>${d[1]}</h3><p>${d[2]}</p><div class="resource-bottom"><span>파일 등록 예정</span>${btn('내용 보기','arrow-right',`data-resource="${i}"`,'small')}</div></article>`).join('')}</div>`;}
function settings(){return `${heading('환경설정','워크스페이스 정보와 운영 환경을 설정하세요.')}<div class="settings-layout"><nav class="panel settings-nav" aria-label="설정 메뉴">${[['basic','기본 정보','building'],['permissions','사용자 · 권한','shield'],['notifications','알림 설정','bell'],['data','데이터 관리','folder']].map(d=>`<button data-setting="${d[0]}" class="${settingsTab===d[0]?'active':''}">${icon(d[2])}${d[1]}</button>`).join('')}</nav><section class="panel settings-body" id="settingsBody">${settingsBody()}</section></div>`;}
function settingsBody(){if(settingsTab==='basic')return `<h2>워크스페이스 기본 정보</h2><p>영업관리 화면에 표시할 기본 정보를 관리합니다.</p><div class="field-grid"><label class="field">워크스페이스명<input value="라이프앤조이"></label><label class="field">브랜드명<input value="소노아임레디 마음든든"></label><label class="field">대표 관리자<input value="총괄관리자"></label><label class="field">운영 이메일<input type="email" placeholder="운영 이메일 입력"></label><label class="field full">상품 랜딩페이지<input type="url" value="https://sono-maeum.vercel.app/"><small>고객에게 안내할 상품 페이지 주소입니다.</small></label><label class="field full">운영 메모<textarea placeholder="파트너에게 안내할 운영 메모를 입력하세요."></textarea></label></div><div class="form-footer">${btn('변경사항 저장','check','data-action="preview-save"','primary')}</div>`;if(settingsTab==='permissions')return `<h2>사용자 · 권한</h2><p>총괄관리자, 운영담당자, 파트너의 접근 범위 제안입니다.</p><div class="table-scroll"><table class="permission-table"><thead><tr><th>역할</th><th>조회 범위</th><th>주요 업무</th></tr></thead><tbody><tr><td><strong>총괄관리자</strong></td><td>전체 조직</td><td>전체 관리 · 설정</td></tr><tr><td>운영담당자</td><td>담당 조직</td><td>고객 상담 · 접수 관리</td></tr><tr><td>파트너</td><td>소속 조직</td><td>고객 등록 · 실적 조회</td></tr></tbody></table></div><div class="section-note">${icon('shield')}실제 계정 인증과 접근 제어는 기능 개발 단계에서 적용합니다.</div><div class="form-footer">${btn('사용자 추가','plus','data-action="new-user"','primary')}</div>`;if(settingsTab==='notifications')return `<h2>알림 설정</h2><p>확인이 필요한 영업 활동의 알림을 설정합니다. 실제 알림은 발송되지 않습니다.</p>${[['신규 상담 접수','새로운 고객 상담이 등록되면 알림을 받습니다.'],['담당 고객 상태 변경','담당 고객의 상담 및 가입 상태 변화를 확인합니다.'],['파트너 입점 신청','신규 파트너의 신청 접수를 확인합니다.'],['납입 확인 필요','납입 상태 확인이 필요한 고객을 안내합니다.']].map(d=>`<label class="toggle-row"><span><strong>${d[0]}</strong><small>${d[1]}</small></span><input type="checkbox" class="switch" checked aria-label="${d[0]} 알림"></label>`).join('')}<div class="form-footer">${btn('알림 설정 저장','check','data-action="preview-save"','primary')}</div>`;return `<h2>데이터 관리</h2><p>고객 및 운영 데이터를 관리하는 화면입니다.</p><div class="toggle-row"><span><strong>데이터 내보내기</strong><small>조건별 고객 목록과 영업 실적을 내려받습니다.</small></span>${btn('내보내기','download','data-action="export"','small')}</div><div class="toggle-row"><span><strong>데이터 초기화</strong><small>초기화 기능은 별도 권한과 확인 절차가 필요합니다.</small></span><button class="button small danger" disabled>개발 시 적용</button></div><div class="section-note">${icon('info')}현재는 예시 화면으로, 실제 고객 데이터가 저장되어 있지 않습니다.</div>`;}
function render(){page=location.hash.slice(1)||'dashboard';if(!titles[page])page='dashboard';renderNav();document.querySelector('#breadcrumbTitle').textContent=titles[page];document.title=`${titles[page]} · 마음든든 영업관리`;const pages={dashboard,customers,partners:partnerPage,applications,products,promotions,overdue,'overdue-new':overdue,statistics,resources,settings};document.querySelector('#main').innerHTML=pages[page]();if(page==='customers')fillCustomerTable();document.querySelector('#sidebar').classList.remove('open');document.querySelector('#mobileShade').classList.remove('open');document.querySelector('#notificationPopover').hidden=true;window.scrollTo({top:0});}
function toast(message){clearTimeout(toastTimer);let t=document.querySelector('#toast');t.textContent=message;t.classList.add('show');toastTimer=setTimeout(()=>t.classList.remove('show'),3600);}
function showDrawer(title,subtitle,body,footer='',tabs=''){lastFocus=document.activeElement;let el=document.querySelector('#drawer');el.innerHTML=`<div class="drawer-head"><div><h2 id="drawerTitle">${title}</h2><p>${subtitle}</p></div><button class="icon-button" data-action="close-drawer" aria-label="상세 패널 닫기">${icon('close')}</button></div>${tabs}<div class="drawer-scroll">${body}</div><div class="drawer-foot"><span class="caption">디자인 미리보기 · 실제 저장 없음</span>${footer||btn('닫기','','data-action="close-drawer"')}</div>`;el.hidden=false;document.querySelector('#drawerOverlay').hidden=false;document.body.style.overflow='hidden';el.querySelector('button').focus();}
function closeDrawer(){document.querySelector('#drawer').hidden=true;document.querySelector('#drawerOverlay').hidden=true;document.body.style.overflow='';if(lastFocus?.isConnected)lastFocus.focus();}
function openCustomer(id,tab='info'){drawerCustomer=data.find(d=>d.id===id);drawerTab=tab;let d=drawerCustomer;if(!d)return;let tabs=`<div class="tabs">${[['info','고객 정보'],['history','상담 이력'],['files','녹취 · 서류']].map(v=>`<button class="tab ${tab===v[0]?'active':''}" data-drawer-tab="${v[0]}">${v[1]}</button>`).join('')}</div>`;let top=`<div class="drawer-customer"><span class="person-circle">${d.name[0]}</span><span><strong>${d.name}</strong><small>${d.phone} · ${d.id}</small></span>${pill(d.status)}</div>`;let body=top;if(tab==='info')body+=`<div class="flow-mini"><span class="done">${icon('check-circle')}상담 접수</span><span class="${d.status!=='접수대기'?'done':''}">${icon('phone')}상담 진행</span><span class="${['녹취완료','정상가입'].includes(d.status)?'done':''}">${icon('mic')}녹취 확인</span><span class="${d.status==='정상가입'?'done':''}">${icon('shield')}정상 가입</span></div><h3 class="section-label">기본 정보</h3><dl class="details-list"><div><dt>고객명</dt><dd>${d.name}</dd></div><div><dt>연락처</dt><dd>${d.phone}</dd></div><div><dt>접수 일시</dt><dd>2026.${d.time}</dd></div><div><dt>유입 경로</dt><dd>${d.channel}</dd></div><div><dt>상위 파트너</dt><dd>라이프앤조이</dd></div><div><dt>담당 파트너</dt><dd>${d.partner}</dd></div></dl><h3 class="section-label">상품 · 가입 정보</h3><div class="note-card"><strong>마음든든 ${d.product} · ${d.units}구좌</strong><br>지정 대상자 및 가입 조건은 상담 단계에서 확인합니다.<br>현재 고객 정보와 가입 내역은 모두 디자인용 예시입니다.</div><h3 class="section-label">상담 관리</h3><div class="field-grid"><label class="field">진행 상태<select>${['접수대기','상담중','부재','보류','녹취완료','정상가입','청약철회','해약','정산완료'].map(x=>`<option ${x===d.status?'selected':''}>${x}</option>`).join('')}</select></label><label class="field">담당자<select>${['김매니저','이매니저','박매니저','미배정'].map(x=>`<option ${x===d.agent?'selected':''}>${x}</option>`).join('')}</select></label><label class="field full">상담 메모<textarea>${d.memo}</textarea></label><label class="field full">다음 상담 일정<input type="datetime-local" value="2026-11-17T14:00"></label></div>`;else if(tab==='history')body+=`<h3 class="section-label">상담 타임라인</h3><div class="timeline"><div class="timeline-item"><time>2026.${d.time} · ${d.agent}</time><h3>고객 상담 내용 기록</h3><div class="note-card">${d.memo}</div></div><div class="timeline-item"><time>2026.11.16 11:30 · 운영담당자</time><h3>상담 담당자 배정</h3><p>${d.partner} · ${d.agent}<br>고객 관심 상품을 확인하고 상담을 준비합니다.</p></div><div class="timeline-item"><time>2026.11.16 10:42 · ${d.channel}</time><h3>신규 상담 접수</h3><p>마음든든 ${d.product} 상담 요청이 접수되었습니다.</p></div></div><div class="field"><label for="historyMemo">새 상담 기록</label><textarea id="historyMemo" placeholder="상담 내용을 입력하세요."></textarea></div><div class="section-note">${icon('info')}이력은 화면 구성 예시이며 실제 고객 활동 기록이 아닙니다.</div>`;else body+=`<h3 class="section-label">녹취 파일</h3><div class="note-card" style="display:flex;gap:12px;align-items:center">${icon('mic')}<span><strong>상담 녹취 파일</strong><br>등록된 실제 파일이 없습니다.</span></div><button class="upload-area" style="width:100%" data-action="file-preview">${icon('upload')}<strong>녹취 파일 업로드</strong><small>MP3, M4A, WAV · 기능 개발 후 연결</small></button><h3 class="section-label">가입 관련 서류</h3><div class="note-card"><strong>서류 등록 예정</strong><br>신청서와 확인 서류를 이 화면에서 관리합니다.</div><h3 class="section-label">본사 접수</h3><div class="toggle-row"><span><strong>소노 본사 접수 상태</strong><small>본사 접수 시스템은 아직 연동되지 않았습니다.</small></span>${pill('연동 대기','gray')}</div>`;showDrawer('고객 상세',d.id+' · 샘플 고객',body,btn('닫기','','data-action="close-drawer"')+btn('미리보기 저장','check','data-action="preview-save"','primary'),tabs);}
function newCustomer(){showDrawer('신규 고객 등록','고객 접수 입력 화면',`<div class="note-card">이 폼은 화면 확인용입니다. 실제 개인정보를 수집하거나 상담을 접수하지 않습니다.</div><h3 class="section-label">고객 정보</h3><div class="field-grid"><label class="field">고객명<input placeholder="예시 고객명"></label><label class="field">연락처<input type="tel" placeholder="010-0000-0000"></label><label class="field">관심 상품<select><option>마음든든 3</option><option>마음든든 4</option><option>마음든든 5</option></select></label><label class="field">가입 구좌<input type="number" min="1" value="1"></label><label class="field">유입 경로<select><option>직접 등록</option><option>상품 랜딩</option><option>인스타그램</option><option>파트너</option></select></label><label class="field">담당 파트너<select><option>본사 직영</option><option>파트너 A</option><option>파트너 B</option><option>파트너 C</option></select></label><label class="field full">상담 메모<textarea placeholder="관심 사항과 상담 희망 시간을 입력하세요."></textarea></label></div>`,btn('취소','','data-action="close-drawer"')+btn('등록 화면 확인','check','data-action="preview-save"','primary'));}
function openPartner(name){let d=partners.find(p=>p[0]===name)||partners[0];showDrawer('파트너 상세',d[1]+' · 예시 조직',`<div class="drawer-customer"><span class="person-circle">${icon('building')}</span><span><strong>${d[0]}</strong><small>상위 조직 · ${d[2]}</small></span>${pill('운영중')}</div><h3 class="section-label">파트너 기본 정보</h3><dl class="details-list"><div><dt>담당자</dt><dd>${d[3]}</dd></div><div><dt>파트너 유형</dt><dd>${d[0]==='본사 직영'?'직영':'제휴 파트너'}</dd></div><div><dt>판매 상품</dt><dd>마음든든 3 · 4 · 5</dd></div><div><dt>상태</dt><dd>운영중</dd></div></dl><h3 class="section-label">영업 현황</h3><div class="metrics-grid" style="grid-template-columns:1fr 1fr">${metric('상담 접수',d[4],'건','phone','이번 달','예시 실적')}${metric('정상 가입',d[5],'건','shield',(d[5]/d[4]*100).toFixed(1)+'%','가입 전환율')}</div><h3 class="section-label">전용 랜딩</h3><div class="note-card">상품 랜딩: sono-maeum.vercel.app<br>파트너별 추적 링크는 기능 개발 후 생성됩니다.</div><h3 class="section-label">관리 메모</h3><label class="field"><textarea placeholder="파트너 운영 메모를 입력하세요."></textarea></label>`,btn('미리보기 저장','check','data-action="preview-save"','primary'));}
function genericForm(type){const config={partner:['파트너 등록','파트너 기본 정보를 입력하는 화면입니다.',['파트너명','담당자명','연락처','운영 이메일'],'운영 메모'],promotion:['프로모션 등록','캠페인 구성과 검토 상태를 관리합니다.',['프로모션명','대상 상품','노출 채널','운영 담당자'],'캠페인 내용'],resource:['자료 등록','자료실에 표시할 정보를 등록합니다.',['자료명','분류','버전','담당자'],'자료 설명'],user:['사용자 추가','운영 사용자 등록 화면입니다.',['사용자명','운영 이메일','소속 조직','역할'],'관리 메모']};let c=config[type];showDrawer(c[0],c[1],`<div class="field-grid">${c[2].map(v=>`<label class="field">${v}<input placeholder="${v} 입력"></label>`).join('')}<label class="field full">${c[3]}<textarea placeholder="내용을 입력하세요."></textarea></label></div><div class="section-note">${icon('info')}입력 화면 미리보기입니다. 실제 계정이나 자료가 생성되지 않습니다.</div>`,btn('취소','','data-action="close-drawer"')+btn('미리보기 저장','check','data-action="preview-save"','primary'));}
function importPanel(){showDrawer('엑셀 업로드','고객 또는 납입 자료 등록 화면',`<div class="note-card">표준 양식 선택 → 파일 업로드 → 내용 확인 → 반영 순서로 구성할 예정입니다.</div><h3 class="section-label">업로드 유형</h3><label class="field"><select><option>신규 고객 접수</option><option>가입 요청 업데이트</option><option>본사 납입 내역</option></select></label><button class="upload-area" style="width:100%" data-action="file-preview">${icon('upload')}<strong>엑셀 파일을 선택하세요</strong><small>XLSX, CSV · 업로드 기능은 추후 연결</small></button><div class="note-card">필수 항목과 중복 고객을 확인한 후 반영하는 검토 화면을 제공합니다.</div>`,btn('닫기','','data-action="close-drawer"'));}
function showProduct(n){let i=n-3;showDrawer('마음든든 '+n+' 상품 정보','제공 랜딩 표기 기준 · 최종 승인 자료 대조 대기',`<div class="note-card">최신 승인 자료 대조가 필요한 상품 정보입니다. 이 화면 자체가 계약 조건을 확정하지 않습니다.</div><h3 class="section-label">상품 기본 정보</h3><dl class="details-list"><div><dt>상품명</dt><dd>마음든든 ${n}</dd></div><div><dt>월 납입액</dt><dd>${['32,000','43,000','54,000'][i]}원</dd></div><div><dt>납입 기간</dt><dd>96회</dd></div><div><dt>총 납입액</dt><dd>${['3,072,000','4,128,000','5,184,000'][i]}원</dd></div><div><dt>장례의전 도우미</dt><dd>${[3,4,6][i]}명</dd></div><div><dt>잔금 보장 구간</dt><dd>25~84회차 · 조건 충족 시</dd></div></dl><h3 class="section-label">안내 시 확인사항</h3><div class="note-card">• 전 구간 월 납입, 총 96회입니다.<br>• 잔금 보장은 사전 지정 1인 등 적용 조건이 있습니다.<br>• 납입 완료와 만기 환급 시점은 다릅니다.<br>• 장례식장 이용료·음식료 등 상품 외 비용은 별도입니다.<br>• 해약환급금은 회차와 계약 기준에 따라 확인합니다.</div><h3 class="section-label">참조 자료</h3><a class="button" target="_blank" rel="noreferrer" href="https://sono-maeum.vercel.app/">${icon('external')}제공 랜딩페이지 확인</a>`,btn('확인','','data-action="close-drawer"','primary'));}
function showApplication(name){showDrawer('입점 신청 상세',name+' · 예시 신청서',`<h3 class="section-label">신청 정보</h3><dl class="details-list"><div><dt>파트너명</dt><dd>${name}</dd></div><div><dt>사업자 유형</dt><dd>법인 / 개인사업자</dd></div><div><dt>영업 예정 상품</dt><dd>마음든든</dd></div><div><dt>신청 상태</dt><dd>심사중</dd></div></dl><h3 class="section-label">심사 체크리스트</h3>${['사업자 정보 확인','담당자 연락처 확인','판매 채널 및 운영 계획 확인','필수 서류 확인'].map(x=>`<label class="toggle-row"><span><strong>${x}</strong></span><input class="checkbox" type="checkbox"></label>`).join('')}<h3 class="section-label">검토 메모</h3><label class="field"><textarea placeholder="검토 내용을 기록하세요."></textarea></label><div class="section-note">${icon('info')}실제 심사나 승인 처리는 이루어지지 않습니다.</div>`,btn('서류보완 화면 확인','','data-action="preview-save"')+btn('승인 화면 확인','check','data-action="preview-save"','primary'));}
function showCampaign(i){let names=['신규 상담 캠페인','파트너 상담 가이드','가입 전 확인 카드뉴스'];showDrawer(names[i],'캠페인 상세 · 화면 예시',`<div class="note-card">실제 캠페인 실행 전 검토하는 관리 화면입니다. 외부 게시와 광고비 집행 기능은 연결되지 않았습니다.</div><h3 class="section-label">캠페인 설정</h3><div class="field-grid"><label class="field full">캠페인명<input value="${names[i]}"></label><label class="field">대상 상품<select><option>마음든든 전체</option><option>마음든든 3</option><option>마음든든 4</option><option>마음든든 5</option></select></label><label class="field">검토 상태<select><option>초안</option><option>검토대기</option><option>승인완료</option><option>종료</option></select></label><label class="field full">안내 문구<textarea>가족을 위한 준비, 납입과 서비스 조건부터 함께 확인하세요.</textarea></label></div><h3 class="section-label">연결 랜딩</h3><div class="note-card">https://sono-maeum.vercel.app/</div>`,btn('미리보기 저장','check','data-action="preview-save"','primary'));}
function showResource(i){let names=['마음든든 상품 안내서','가입 전 확인 체크리스트','파트너 상담 스크립트','고객 접수 양식','브랜드 디자인 가이드','파트너센터 이용 가이드'];let bullets=[['상품별 월 납입액·총 납입액','서비스 구성 및 추가 비용','이용·해약·환급 조건'],['월 납입액과 총 납입금액 확인','서비스 이용 시점과 대상 확인','중도 해약 및 만기 조건 확인'],['고객 상담 목적 확인','관심 상품의 조건 안내','질문 확인 및 후속 상담 기록'],['고객 기본 정보','관심 상품과 유입 경로','담당 파트너와 상담 내용'],['딥그린·아이보리·세이지 컬러','브랜드 표시 및 여백 기준','파트너 홍보물 적용 예시'],['고객 등록과 상태 관리','파트너별 영업 현황','자료 및 운영 정보 관리']];showDrawer(names[i],'자료실 상세 · 파일 등록 예정',`<div class="empty-state">${icon('file')}<strong>승인된 자료를 등록할 자리입니다.</strong><p>아직 실제 파일이 연결되어 있지 않습니다.</p></div><h3 class="section-label">수록 내용 예시</h3><div class="note-card">${bullets[i].map(x=>'• '+x).join('<br>')}</div>`,btn('닫기','','data-action="close-drawer"'));}
function notifications(){let p=document.querySelector('#notificationPopover');p.hidden=!p.hidden;if(!p.hidden)p.innerHTML=`<h3>알림 <span class="pill gray">예시</span></h3><a class="task-row" href="#customers"><span class="task-icon">${icon('users')}</span><span><strong>신규 상담을 확인하세요</strong><small>접수대기 고객 12건</small></span></a><a class="task-row" href="#applications"><span class="task-icon">${icon('building')}</span><span><strong>새로운 파트너 신청</strong><small>검토가 필요한 신청 3건</small></span></a><div class="task-foot">실제 운영 알림이 아닌 디자인 예시입니다.</div>`;}
document.addEventListener('click',e=>{
 const action=e.target.closest('[data-action]');const task=e.target.closest('[data-task-filter]');if(task){customerFilter=task.dataset.taskFilter;pageNumber=1;}
 const cust=e.target.closest('[data-customer]');if(cust&&!e.target.closest('input')){openCustomer(cust.dataset.customer);return;}
 const partner=e.target.closest('[data-partner]');if(partner){openPartner(partner.dataset.partner);return;}
 const dt=e.target.closest('[data-drawer-tab]');if(dt){openCustomer(drawerCustomer.id,dt.dataset.drawerTab);return;}
 const pg=e.target.closest('[data-page]');if(pg){pageNumber=Number(pg.dataset.page);fillCustomerTable();return;}
 const st=e.target.closest('[data-setting]');if(st){settingsTab=st.dataset.setting;render();return;}
 const prod=e.target.closest('[data-product]');if(prod){showProduct(Number(prod.dataset.product));return;}
 const org=e.target.closest('[data-org]');if(org){document.querySelectorAll('[data-org]').forEach(b=>b.classList.toggle('selected',b===org));let v=org.dataset.org;document.querySelector('#partnerRows').innerHTML=partnerRows(partners.filter(d=>v==='all'||v==='라이프앤조이'||d[0]===v));return;}
 const application=e.target.closest('[data-application]');if(application){showApplication(application.dataset.application);return;}
 const camp=e.target.closest('[data-campaign]');if(camp){showCampaign(Number(camp.dataset.campaign));return;}
 const res=e.target.closest('[data-resource]');if(res){showResource(Number(res.dataset.resource));return;}
 if(!action)return;switch(action.dataset.action){
 case 'new-customer':newCustomer();break;case 'close-drawer':closeDrawer();break;
 case 'new-partner':genericForm('partner');break;case 'new-promotion':genericForm('promotion');break;case 'new-resource':genericForm('resource');break;case 'new-user':genericForm('user');break;
 case 'preview-save':toast('입력 화면을 확인했습니다. 실제 데이터는 저장되지 않습니다.');break;
 case 'export':toast('다운로드 화면 버튼입니다. 실제 엑셀·리포트 생성은 추후 연결합니다.');break;
 case 'import':importPanel();break;case 'file-preview':toast('파일 업로드는 기능 개발 단계에서 연결합니다.');break;
 case 'customer-tab':customerFilter=action.dataset.value;pageNumber=1;render();break;
 case 'reset-filter':customerFilter='전체';search='';productFilter='전체 상품';partnerFilter='전체 파트너';pageNumber=1;render();break;
 case 'chart':chartPeriod=action.dataset.value;document.querySelectorAll('[data-action="chart"]').forEach(b=>b.classList.toggle('active',b===action));document.querySelector('#chartWrap').innerHTML=lineChart();break;
 case 'date':document.querySelector('#datePanel').hidden=!document.querySelector('#datePanel').hidden;break;
 case 'range':document.querySelector('#dateFrom').value=action.dataset.range==='week'?'2026-11-10':'2026-11-01';document.querySelector('#dateTo').value='2026-11-16';break;
 case 'apply-date':{let f=document.querySelector('#dateFrom').value,t=document.querySelector('#dateTo').value;if(!f||!t||f>t){toast('시작일과 종료일을 확인하세요.');break;}document.querySelector('#dateLabel').textContent=f.replaceAll('-','.')+' – '+t.replaceAll('-','.');document.querySelector('#datePanel').hidden=true;toast('조회 기간 표시를 변경했습니다. 수치는 디자인용 예시입니다.');break;}
 case 'arrears-tab':document.querySelectorAll('[data-action="arrears-tab"]').forEach(b=>b.classList.toggle('active',b===action));document.querySelector('#arrearsRows').innerHTML=arrearsRows(action.dataset.value,document.querySelector('#arrearsSearch').value);break;
 }
});
document.addEventListener('input',e=>{if(e.target.id==='customerSearch'){search=e.target.value;pageNumber=1;fillCustomerTable();}if(e.target.id==='partnerSearch'){let q=e.target.value;document.querySelector('#partnerRows').innerHTML=partnerRows(partners.filter(d=>d.join(' ').includes(q)));}if(e.target.id==='arrearsSearch'){document.querySelector('#arrearsRows').innerHTML=arrearsRows(document.querySelector('[data-action="arrears-tab"].active').dataset.value,e.target.value);}});
document.addEventListener('change',e=>{if(e.target.id==='productFilter'){productFilter=e.target.value;pageNumber=1;fillCustomerTable();}if(e.target.id==='partnerFilter'){partnerFilter=e.target.value;pageNumber=1;fillCustomerTable();}if(e.target.matches('[data-select-all]'))document.querySelectorAll('.row-check').forEach(c=>c.checked=e.target.checked);});
document.addEventListener('keydown',e=>{if(e.key==='Escape'){closeDrawer();document.querySelector('#notificationPopover').hidden=true;document.querySelector('#sidebar').classList.remove('open');document.querySelector('#mobileShade').classList.remove('open');}if(e.key==='Enter'&&e.target.matches('tr[data-customer]'))openCustomer(e.target.dataset.customer);if(e.key==='Tab'&&!document.querySelector('#drawer').hidden){let fs=[...document.querySelector('#drawer').querySelectorAll('button,a,input,select,textarea,[tabindex="0"]')].filter(el=>!el.disabled);let a=fs[0],b=fs[fs.length-1];if(e.shiftKey&&document.activeElement===a){e.preventDefault();b.focus();}else if(!e.shiftKey&&document.activeElement===b){e.preventDefault();a.focus();}}});
document.querySelector('#drawerOverlay').addEventListener('click',closeDrawer);
document.querySelector('#mobileToggle').addEventListener('click',()=>{document.querySelector('#sidebar').classList.toggle('open');document.querySelector('#mobileShade').classList.toggle('open');});
document.querySelector('#mobileShade').addEventListener('click',()=>{document.querySelector('#sidebar').classList.remove('open');document.querySelector('#mobileShade').classList.remove('open');});
document.querySelector('#notificationButton').addEventListener('click',notifications);
document.querySelector('#globalSearch').addEventListener('click',()=>{customerFilter='전체';if(location.hash==='#customers'){document.querySelector('#customerSearch').focus();}else{location.hash='customers';setTimeout(()=>document.querySelector('#customerSearch')?.focus(),60);}});
window.addEventListener('hashchange',render);
renderIcons();render();
